def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys and values on defaults mode=fast and level=3, returning values for mode, level, and extra keys in order."""
    pre keys.len() == values.len()
    ex settings(keys=[], values=[]) == ["fast", "3"]
    ex settings(keys=["timeout"], values=["10"]) == ["fast", "3", "10"]
    ex settings(keys=["level", "mode"], values=["5", "slow"]) == ["slow", "5"]
    mode = "fast"
    level = "3"
    extra_keys: list[str] = []
    extra_values: dict[str, str] = {}
    for i in range(keys.len()):
        k = keys[i]
        v = values[i]
        if k == "mode":
            mode = v.copy()
        elif k == "level":
            level = v.copy()
        else:
            if k not in extra_values:
                extra_keys.append(k.copy())
            extra_values[k] = v.copy()
    out = [mode, level]
    for k in extra_keys:
        out.append(extra_values.get(k) else "")
    return out

